  [11433111] = "%s tuned the lighting perfectly. Now the library was much brighter lit.",
  [11433112] = "%s was more skilled with tuning stage lights and was not very familiar with indoor situations such as libraries.",
  [11433113] = "%s made the lighting too bright that it felt like staring into the sun.",
  [11433114] = "%s's misoperation on light tuning accidentally burned out the entire electric system in the library.",
  [11433119] = "We couldn't find any lighting engineer with the right knowledge. Looks like we'll have to do it ourselves.",
