  [12056102] = "Have the whole crew thank the viewers on camera.",
  [12056103] = "In-depth interview with the celeb about the show.",
  [12056111] = "You can do that, but is it really special or unique?",
  [12056112] = "The plan adds a lot of human dimensions to the show.",
  [12056113] = "The fans of the celeb are dying in anticipation for the episode.",
  [12056120] = "No money, no romance, no quaintness, no sophistication.",
  [12056200] = "Who do you get to set up the scene for the grand finale?",
  [12056211] = "%s turns in an eye-catching, theme-fitting effort.",
