  [12134112] = "%s writes a script like a modern family soap opera, which is awkward.",
  [12134113] = "%s's script is too lengthy to be a mini drama at all.",
  [12134114] = "%s copies other's work, making the crew criticized by the public.",
  [12134119] = "You decide to collect true stories from the public on the Internet.",
  [12134120] = "This is what it feels like to be at home!",
  [12134200] = "The crew needs to find a composer to compose background music for the drama.",
  [12134211] = "%s boldly uses traditional instruments and as a result, the background music is warm and moving.",
  [12134212] = "It is the story of Chinese families, but %s uses western electronic music, which is incongruous.",
  [12134213] = "%s uses some ad music, and the audience doesn't like it.",
  [12134214] = "%s makes a mistake in the scenes that need background music, making all the background music appear at the wrong times.",
  [12134219] = "You plan to use classic music as background music.",
  [12134220] = "Very effective!",
