  [12160213] = "The cameras set up by %s are so remote that they can't fully record the vivid expressions of the kids.",
  [12160214] = "A camera set up by %s is placed in an inappropriate place. A kid accidentally bumps into it and gets injured.",
  [12160219] = "Thanks to the parents, they manage to find out the suitable places for setting up the cameras in their home.",
  [12160220] = "The parents really rock!",
  [12161000] = "Our parents are aging. This is a leisure variety show that invites stars and their parents to travel together.",
  [12161001] = "There are too many disguises in the world... I was tired of staying perfect. When I was dispirited, I suddenly remembered what he said...",
  [12161002] = "You taught me to walk when I was young; I lead you to walk when you are old.",
