  [12161111] = "%s carries all kinds of medicines ready for the possible diseases of the elderly, which is reassuring.",
  [12161112] = "%s isn't familiar with senile diseases and carries the wrong medicines.",
  [12161113] = "%s shows a bad attitude and isn't patient with the elderly.",
  [12161114] = "%s prepared a huge luggage, in which are nothing but clothes...",
  [12161119] = "Just count on local medical resources.",
  [12161120] = "Don't make a mountain out of a molehill...",
  [12161200] = "You need a person to handle the logistics. Who will you choose?",
  [12161201] = " ",
  [12161211] = "%s prepares many practical stuff and is praised by everyone.",
