  [12164113] = "%s's props are at such a high price that the program can't afford them.",
  [12164114] = "%s mixed the props and the clues, forcing the program to be shot again.",
  [12164119] = "Why not let the guests prepare for themselves?",
  [12164120] = "I'm really good at saving money!",
  [12164200] = "You need a musician to compose music for the program. Who will you choose?",
