  [18046111] = "The contents %s wrote were lively and well received by people of all ages!",
  [18046112] = "%s didn't prepare it carefully as many introductions were wrong.",
  [18046113] = "The script %s wrote was just like TV shopping ads...",
  [18046114] = "The contents %s wrote were not as good as those written by pupils and were full of ill-formed sentences.",
  [18046119] = "It was about searching for information and writing. I might be able to do it...",
  [18046120] = "Is it not okay to directly quote the museum introductions?",
  [18046200] = "The shooting ended. It was time to tidy up the site with the museum staff!",
  [18046201] = " ",
  [18046211] = "Diligent and enthusiastic, %s tidied up the site very soon.",
