  [18311102] = "Spicy Lobster",
  [18311103] = "Duck Blood Vermicelli",
  [18311111] = "Carrying essential items around is a detail a mature producer shouldn't overlook.",
  [18311112] = "Theoretically, it probably can't be carried around.",
  [18311113] = "But a mature office lady should carry something else, right?",
  [18311119] = "Even if I forget something, I should still be able to find them in the office, right...?",
  [18311120] = "Recorder pens and notebooks have always been my faithful partners.",
  [18312000] = "It's the commencement ceremony of high school today. I can't be late.",
  [18312001] = "After all that's happened, my legs can barely move, my eyes can barely see. I no longer have the strength to struggle. But as I'm on the verge of giving up, his face flashes through my mind...",
  [18312002] = "I hope it'll go smoothly today.",
  [18312100] = "I should bring a snack, in case I get hungry in the afternoon.",
  [18312101] = "Soup Dumplings",
  [18312102] = "Bread",
  [18312103] = "Hot Pot",
  [18312111] = "It'll be cold by the afternoon... Let's choose something else.",
  [18312112] = "It's neither too big nor too small, but it'd be perfect with a sausage.",
  [18312113] = "I feel like it isn't easy to carry around...",
  [18312119] = "If all else fails, I'll just buy some at the snack shop.",
  [18312120] = "I'm no longer the person who'd run late and rush out the door with a slice of bread in my mouth.",
  [18313000] = "After a long day of work, it's finally time to go home!",
  [18313001] = "My legs can barely move, my eyes can barely see. I no longer have the strength to struggle. But as I'm on the verge of giving up, his face flashes through my mind...",
  [18313002] = "It's a nice day today. It doesn't look like it's gonna thunder or rain.",
