  [18326113] = "I wonder how you use this to tie back your hair...?",
  [18327000] = "High as heaven, fleet as wind, the flute sounds its winsome melody...",
  [18327001] = "I don't know whether my decision will bring me light or push me towards the abyss. But as I hesitate, a warm voice speaks to me inside my mind...",
  [18327002] = "All I wish for, is a harmonious life.",
  [18327100] = "The breeze is blowing. You pull out a small flute and start to play a tune. It is one you know well...",
  [18327101] = "Bamboo Leaf",
  [18327102] = "Dragon Well Tea",
  [18327103] = "Trigram Mirror",
  [18327111] = "So, you can play this song, too?",
