  [18332101] = "Catch the plates, like they do in the comic books",
  [18332102] = "Pull Lucien out of the way",
  [18332103] = "Freeze in place",
  [18332111] = "NO!!!",
  [18332112] = "Your quick thinking saves Lucien a lot of embarrassment.",
  [18332113] = "At times like this some movement is advisable...",
  [18332120] = "Luckily no one got covered in food...",
  [18332200] = "They're about to set off the fireworks! Find a good spot to watch them.",
