  [18333112] = "It doesn't look like he can see you...",
  [18333113] = "There are no empty baskets nearby...",
  [18333120] = "Did he really not see me?",
  [18333200] = "There's all kinds of animal-shaped candies on the stall. Go ahead, pick one!",
  [18333201] = "Three-headed Nine-tailed Serpent",
  [18333202] = "Deep Sea Abomination",
  [18333203] = "Bunny",
  [18333211] = "The cook has a very good imagination...",
  [18333212] = "What... the hell... is that?",
  [18333213] = "Cute little bunny, sweet in the middle. Give Kiro a bite.",
  [18333220] = "Have some of my sweet.",
  [18334000] = "Kiro seems fascinated by everything. It only makes me want to be with him more and make tonight a perfect night...",
  [18334001] = "My legs can barely move, my eyes can barely see. I no longer have the strength to struggle. But as I'm on the verge of giving up, his face flashes through my mind...",
  [18334002] = "It WAS a perfect night, even if it was full of surprises.",
