  [18346111] = "你发现工作人员的热情并不会被轻易地浇灭",
  [18346112] = "你跟着他们逛遍了整个商场，脑袋空空，钱包空空",
  [18346113] = "你成功地逃离了现场",
  [18346120] = "呼……",
  [18346200] = "摆脱了热情的工作人员，接下来你打算去哪个店面呢？",
  [18346201] = "主题餐厅",
  [18346202] = "奢侈品店",
